package gg.pixelkingdomwars.nativeclient.ordinaryequipment
import gg.pixelkingdomwars.nativeclient.charter.*
import gg.pixelkingdomwars.nativeclient.starter.StarterIdentity
import gg.pixelkingdomwars.nativeclient.vehicle.*
import kotlinx.serialization.json.*
import org.junit.Assert.*
import org.junit.Test
class EquipmentProtocolTest {
 private val f=Json.parseToJsonElement(requireNotNull(javaClass.getResource("/ordinary-equipment.json")).readText()).jsonObject
 private val policy=EquipmentPolicy.from(f.charterObject("policy"));private val identity=StarterIdentity("https://equipment.test","devnet",f.charterObject("view").charterText("wallet"))
 private val recipe=EquipmentView.from(f.charterObject("view")).recipes.single();private val command=EquipmentCommand(EquipmentGrammar.craftRequest(f.charterObject("request")),recipe)
 private fun change(o:JsonObject,path:String,value:JsonElement):JsonObject {val p=path.split('.',limit=2);return JsonObject(o+(p[0] to if(p.size==1)value else change(o.charterObject(p[0]),p[1],value)))}
 private fun reject(block:()->Unit){assertThrows(Exception::class.java,block)}
 @Test fun `canonical recipe stock and frozen original craft remain exact`() {policy.verify(recipe);EquipmentProof.from(f.charterObject("envelope"),identity,command);assertEquals("route_compass",recipe.output.itemId);assertEquals("1",EquipmentView.from(f.charterObject("view")).equipmentStock.single().pendingOutput)}
 @Test fun `forged craft actor base materials output and duration are held`() {for((p,v) in listOf("wallet" to JsonPrimitive("11111111111111111111111111111113"),"receipt.request.baseId" to JsonPrimitive("00000000-0000-4000-8000-000000000099"),"receipt.recipe.output.quantity" to JsonPrimitive("99"),"receipt.recipe.durationSec" to JsonPrimitive(1)))reject{EquipmentProof.from(change(f.charterObject("envelope"),p,v),identity,command)}}
 @Test fun `negative string numeric unknown field duplicate stock and conservation failures reject`() {val original=f.charterObject("view");val equipment=original.getValue("equipmentStock").jsonArray.single().jsonObject
  for(v in listOf(JsonPrimitive("-1"),JsonPrimitive(1),JsonPrimitive("9223372036854775808")))reject{EquipmentView.from(JsonObject(original+("equipmentStock" to JsonArray(listOf(JsonObject(equipment+("available" to v)))))))}
  reject{EquipmentView.from(JsonObject(original+("walletAuthority" to JsonPrimitive(true))))};reject{EquipmentView.from(JsonObject(original+("craftingStock" to JsonArray(original.getValue("craftingStock").jsonArray+original.getValue("craftingStock").jsonArray.first()))))};reject{EquipmentView.from(JsonObject(original+("pendingJobs" to JsonArray(emptyList()))))}}
 @Test fun `unsupported request versions quantities and injected actors cannot leave transport`() {for((k,v) in listOf("quantity" to JsonPrimitive(2),"recipeVersion" to JsonPrimitive(2),"wallet" to JsonPrimitive(identity.wallet)))reject{EquipmentGrammar.request("POST","/ordinary-equipment/jobs",emptyMap(),JsonObject(f.charterObject("request")+(k to v)))}
  reject{EquipmentGrammar.request("GET","/ordinary-equipment",mapOf("baseId" to command.request.baseId,"wallet" to identity.wallet),null)};reject{EquipmentGrammar.request("POST","/ordinary-equipment/jobs/cancel",emptyMap(),f.charterObject("request"))}}
 @Test fun `starter retained fitting uses ceil duration and tax compatible reduced cargo`() {val envelope=f.charterObject("starterEnvelope");val r=envelope.charterObject("receipt");EquipmentGrammar.starterProof(envelope,identity,r.charterObject("request"),r.charterObject("route"),policy);assertEquals("25",policy.original(r.charterObject("route")).charterText("grossQuantity"));assertEquals("15",r.charterObject("route").charterText("grossQuantity"))}
 @Test fun `forged fitting snapshots lost fitting or altered returns cannot match reviewed route`() {val envelope=f.charterObject("starterEnvelope");val r=envelope.charterObject("receipt");for((p,v) in listOf("receipt.route.durationSec" to JsonPrimitive(1),"receipt.route.grossQuantity" to JsonPrimitive("18"),"receipt.route.fitting.policyVersion" to JsonPrimitive(2),"receipt.returnsAt" to JsonPrimitive("2035-01-01T00:23:59.000Z"),"receipt.request.fitting" to JsonNull))reject{EquipmentGrammar.starterProof(change(envelope,p,v),identity,r.charterObject("request"),r.charterObject("route"),policy)}}
 @Test fun `advanced fitting verifies original canonical route and preserves absent fitting legacy`() {val legacy=Json.parseToJsonElement(requireNotNull(javaClass.getResource("/vehicle-client-vectors.json")).readText()).jsonObject.charterObject("constants");val vp=VehiclePolicy.from(JsonObject(legacy+("ordinaryEquipment" to policy.raw)));val envelope=f.charterObject("advancedEnvelope");vp.verifyExpedition(envelope);val route=envelope.charterObject("receipt").charterObject("route");vp.verifyRoute(policy.original(route));assertEquals(VehiclePolicy.from(legacy).raw,legacy);assertTrue(vp.sameBurnPolicy(VehiclePolicy.from(legacy)))}
 @Test fun `tiny cargo cannot create zero stock or bypass frozen request fitting`() {val route=f.charterObject("starterEnvelope").charterObject("receipt").charterObject("route");val tiny=change(change(change(route,"fitting.originalGrossQuantity",JsonPrimitive("5")),"fitting.originalNetQuantity",JsonPrimitive("4")),"fitting.originalIslandPoolQuantity",JsonPrimitive("1"));reject{policy.original(tiny)}
  val advanced=f.charterObject("advancedEnvelope");reject{VehicleProtocol.expedition(change(advanced,"receipt.request.fitting",JsonNull))}}
 @Test fun `fitted query is exact and only dedicated route endpoints may carry it`() {val base=command.request.baseId;for(path in listOf("/starter-expeditions","/vehicles/client/routes"))EquipmentGrammar.request("GET",path,mapOf("baseId" to base,"fitting" to "route_compass"),null)
  for(path in listOf("/ordinary-equipment","/vehicles/fleet"))reject{EquipmentGrammar.request("GET",path,mapOf("baseId" to base,"fitting" to "route_compass"),null)};reject{EquipmentGrammar.request("GET","/starter-expeditions",mapOf("baseId" to base,"fitting" to "other"),null)}}
}
